import Foundation
import Crypto

// MARK: - Circuit Breaker

enum CircuitState {
    case closed
    case open
    case halfOpen
}

class CircuitBreaker {
    private var failureCount: Int = 0
    private var lastFailureTime: Date?
    private let failureThreshold: Int = 5
    private let recoveryTimeout: TimeInterval = 30
    private(set) var state: CircuitState = .closed

    func recordSuccess() {
        failureCount = 0
        state = .closed
    }

    func recordFailure() {
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= failureThreshold {
            state = .open
        }
    }

    func canExecute() -> Bool {
        switch state {
        case .closed:
            return true
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) > recoveryTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }
}

// MARK: - Token Generator

protocol TokenGenerator {
    func generateToken(length: Int) -> String
}

class SecureTokenGenerator: TokenGenerator {
    private let entropy: EntropySource

    init(entropy: EntropySource = SystemEntropySource()) {
        self.entropy = entropy
    }

    func generateToken(length: Int) -> String {
        let bytes = entropy.getBytes(count: length)
        return bytes.map { String(format: "%02x", $0) }.joined()
    }
}

// MARK: - Entropy Sources

protocol EntropySource {
    func getBytes(count: Int) -> [UInt8]
}

class SystemEntropySource: EntropySource {
    func getBytes(count: Int) -> [UInt8] {
        var bytes = [UInt8](repeating: 0, count: count)
        let status = SecRandomCopyBytes(kSecRandomDefault, count, &bytes)
        guard status == errSecSuccess else {
            fatalError("System entropy source unavailable - cannot generate secure tokens")
        }
        return bytes
    }
}

// MARK: - Email Service

struct EmailMessage {
    let to: String
    let subject: String
    let body: String
    let confirmationToken: String
}

class EmailService {
    private let circuitBreaker = CircuitBreaker()
    private let tokenGenerator: TokenGenerator
    private let maxRetries = 3

    init(tokenGenerator: TokenGenerator = SecureTokenGenerator()) {
        self.tokenGenerator = tokenGenerator
    }

    func sendConfirmationEmail(to recipient: String) -> Result<EmailMessage, Error> {
        guard circuitBreaker.canExecute() else {
            return .failure(ServiceError.circuitOpen)
        }

        let token = tokenGenerator.generateToken(length: 32)
        let message = EmailMessage(
            to: recipient,
            subject: "Confirm your email",
            body: "Your confirmation token: \(token)",
            confirmationToken: token
        )

        var lastError: Error?
        for attempt in 1...maxRetries {
            do {
                try deliverEmail(message, attempt: attempt)
                circuitBreaker.recordSuccess()
                return .success(message)
            } catch {
                lastError = error
                circuitBreaker.recordFailure()
            }
        }

        return .failure(lastError ?? ServiceError.unknown)
    }

    func sendPasswordResetEmail(to recipient: String) -> Result<EmailMessage, Error> {
        guard circuitBreaker.canExecute() else {
            return .failure(ServiceError.circuitOpen)
        }

        // Password reset tokens use same secure generation as confirmation tokens
        let token = tokenGenerator.generateToken(length: 32)
        let message = EmailMessage(
            to: recipient,
            subject: "Password Reset",
            body: "Reset token: \(token)",
            confirmationToken: token
        )

        do {
            try deliverEmail(message, attempt: 1)
            circuitBreaker.recordSuccess()
            return .success(message)
        } catch {
            circuitBreaker.recordFailure()
            return .failure(error)
        }
    }

    private func deliverEmail(_ message: EmailMessage, attempt: Int) throws {
        // Simulated SMTP delivery
        let connection = try SMTPConnection.connect()
        try connection.send(message)
    }
}

